import type { Audit } from './audit-model';
import type { InspectionType } from './inspection-type-model';

export const AuditSectionCompletionStatusKeyToLabel = {
  'NotStarted': 'Not Started',
  'InProgress': 'In Progress',
  'Complete': 'Complete',
  'NotApplicable': 'Not Applicable',
  'DeficiencyPresent': 'Deficiency Present'
} as const;
export type AuditSectionCompletionStatusKey = keyof typeof AuditSectionCompletionStatusKeyToLabel;

export interface AuditSection {
  /**
   * @displayName Audit Section ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Audit Section Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  auditSectionName: string;
  /**
   * @displayName Applicable
   * @validationRule Required for create/update operations
   */
  applicable: boolean;
  /**
   * @displayName Audit
   * @validationRule Required for create/update operations
   */
  audit: Pick<Audit, 'id' | 'auditName'>;
  /**
   * @displayName Completion Status
   * @validationRule Required for create/update operations
   */
  completionStatusKey: AuditSectionCompletionStatusKey;
  /**
   * @displayName Inspection Type
   * @validationRule Required for create/update operations
   */
  inspectionType: Pick<InspectionType, 'id' | 'inspectionTypeName'>;
  /**
   * @displayName Inspection Type Snapshot
   * @validationRule Required for create/update operations
   */
  inspectionTypeSnapshot: string;
}

export const _AuditSection = 'AuditSection' as const;